SELECT * FROM demand_items WHERE is_delete = 0
AND ( title LIKE CONCAT('%', TRIM(#{keyword}), '%') OR summary LIKE CONCAT('%', TRIM(#{keyword}), '%') OR llm_summary LIKE CONCAT('%', TRIM(#{keyword}), '%') OR raw_content LIKE CONCAT('%', TRIM(#{keyword}), '%') OR industry LIKE CONCAT('%', TRIM(#{keyword}), '%') OR region LIKE CONCAT('%', TRIM(#{keyword}), '%') OR source_site LIKE CONCAT('%', TRIM(#{keyword}), '%') OR keywords_json LIKE CONCAT('%', TRIM(#{keyword}), '%') )
AND status = #{status}
AND industry = #{industry}
AND region = #{region}
ORDER BY captured_at DESC, created_at DESC, id DESC
